int BFIndex(String S, int start, String T)
{    int i = start, j = 0, v;
     while(i < S.length && j < T.length)
     {        if(S.str[i] == T.str[j]) {i++; j++;   }
              else{ i = i-j+1; j = 0;               }
     }
     if (j==T.length) v=i-T.length;
     else v=-1;
     return v;
}


